import React, { useState } from "react";
import "./SignUp.css";
import Header from "../components/header";
import Footer from "../components/footer";
import BlurText from "../components/blurtext";

const SignUp = () => {
  const [name, setName] = useState("");
  const [email, setEmail] = useState("");
  const [password, setPassword] = useState("");
  const [confirmPassword, setConfirmPassword] = useState("");
  const [showPassword, setShowPassword] = useState(false);
  const [showConfirmPassword, setShowConfirmPassword] = useState(false);

  const handleSignUp = async (e) => {
    e.preventDefault();
    if (password !== confirmPassword) {
      alert("Passwords do not match!");
      return;
    }

    try {
      const res = await fetch("http://localhost:5000/api/signup", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ name, email, password })
      });

      const data = await res.json();
      if (res.status === 201) {
        alert(data.message);
        window.location.href = "/signin";
      } else {
        alert(data.message);
      }
    } catch (err) {
      console.log(err);
      alert("Error connecting to server");
    }
  };

  return (
    <>
      <Header />
      <div className="signup-container">
        <div className="signup-left">
          <h1><BlurText text="Compare and save big." delay={0.03} /></h1>
          <p><BlurText text="Unlock the best deals." delay={0.05} /></p>
        </div>
        <div className="signup-right">
          <h2>Sign Up</h2>
          <p>Create your smart shopping account</p>

          <form onSubmit={handleSignUp}>
            <label>Name</label>
            <input type="text" value={name} onChange={(e) => setName(e.target.value)} required />

            <label>Email</label>
            <input type="email" value={email} onChange={(e) => setEmail(e.target.value)} required />

            <label>Password</label>
            <div className="password-input-wrapper">
              <input type={showPassword ? "text" : "password"} value={password} onChange={(e) => setPassword(e.target.value)} required />
              <button type="button" onClick={() => setShowPassword(!showPassword)}>👁</button>
            </div>

            <label>Confirm Password</label>
            <div className="password-input-wrapper">
              <input type={showConfirmPassword ? "text" : "password"} value={confirmPassword} onChange={(e) => setConfirmPassword(e.target.value)} required />
              <button type="button" onClick={() => setShowConfirmPassword(!showConfirmPassword)}>👁</button>
            </div>

            <button type="submit">Create Account</button>
          </form>
          <p>Already have an account? <a href="/signin">Sign In</a></p>
        </div>
      </div>
      <Footer />
    </>
  );
};

export default SignUp;
